css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); border-radius: 50%; background: color-mix(in srgb, var(--accent-2) 22%, transparent); position: relative; overflow: hidden; }
.loader::before, .loader::after { content: ''; position: absolute; top: 0; left: 50%; width: 50%; height: 100%; background: var(--accent); transform-origin: left center; }
.loader::before { animation: pie-a calc(var(--loader-speed) * 2.4) linear infinite; }
.loader::after { animation: pie-b calc(var(--loader-speed) * 2.4) linear infinite; }
@keyframes pie-a { 0% { transform: rotate(0deg); } 50%, 100% { transform: rotate(180deg); } }
@keyframes pie-b { 0%, 50% { transform: rotate(0deg); } 100% { transform: rotate(180deg); } }
